-- DRep group pages (tests/drep-groups.spec.ts). A permissioned group founded at height 0xe2e00a,
-- managed 2 of 3 by the test wallet's DRep key (account 0 of the default test mnemonic, key hash
-- a5b45515a3ff8cb7c02ce351834da324eb6dfc41b5779cb5e6b832aa), Alice and Erin, the admission policy
-- the same as the control policy. Bob's request to join at 0xe2e01e is pending, and the wallet DRep
-- opened an approval of it that needs the wallet and Alice: Alice signed, Erin signed as an
-- optional signer. Carol is a registered key DRep outside the group for the founding wizard.
-- Alice, Bob, Carol and Erin are the fixed ed25519 test keys 1, 2, 3 and 5 of the group route tests.
-- The engine rows below were produced by running the group engine and the action routes over this
-- history, so they are consistent with each other. They replace the single drep_group_meta row,
-- which moves the local group index frontier to this fixture history.
DELETE FROM notifications WHERE event_key IN ('e2e-group-join:group1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq8zuq9qqqqwesjwz', 'group-sign:e2e00000000000000000000000000a01');
